style.css:
@-moz-document url-prefix("https://ppomppu.co.kr"), url-prefix("https://www.ppomppu.co.kr") {
/* Ppomppu is an old-school, table-heavy legacy site. It declares a handful of
     :root custom properties but barely uses them (var(--color-basic) appears 3
     times in the whole sheet), so a token remap buys nothing: colours are
     hardcoded per element (white wrappers over a transparent <body>,
     grey table rows/cells, literal hex borders). The retheme paints a dark base
     on the root, then overrides every light wrapper / row / cell / input / menu
     to a dark equivalent, softens the bright gridlines, and remaps the dark body
     text to a light tone. Brand + semantic colours (the hot-deal highlight, the
     blue recommend CTA, price text, the red "report" and orange "other-opinion"
     accents, link blue) are preserved — only their tone is refined to sit well
     on the dark canvas. */

  :root {
    color-scheme: dark;
  }

  /* ---- Base ---------------------------------------------------------------- */
  html {
    background-color: #14181d !important;
  }

  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* Generic text default — the legacy markup hardcodes near-black / dark-grey
     text colours on countless nodes (logo text, list cells, post body, comment
     notices, home tabs). They read fine on the original white but go
     dark-on-dark here, so force the common body text to a readable light tone.
     Semantic colours (blue links, hot/price/report accents) are re-asserted
     after this with their own rules. */
  body,
  td, th, p, li, dt, dd, span, div, a, font, label, b, strong, em, small, em,
  time, nobr, h1, h2, h3, h4, h5, h6 {
    color: #c4cdd6 !important;
  }

  /* ---- Soften light borders & gridlines ------------------------------------ */
  * {
    border-color: #2d333b !important;
  }

  /* ---- Page wrappers / content shells -------------------------------------- */
  .wrapper,
  .container,
  .contents,
  #contents_view,
  .contents_header,
  .contents_header.abs {
    background-color: #14181d !important;
  }

  /* ---- Header / search bar ------------------------------------------------- */
  .header,
  #gnb,
  .top_header {
    background-color: #0d1117 !important;
  }

  .input-search,
  .search_box,
  .search_wrap {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Search-box "인기검색어" (hot-keyword) flyout — opened by the ▼ toggle beside
     the board/forum search field (#subpage-hot-keyword). The site renders the
     ranked-keyword panel (.hot-keyword-wrapper) on a hardcoded pure-white bg, so
     the flyout ships as a bright white popover and the light keyword labels land
     light-on-white = washed out. Closed by default, so the white-surface scan
     never sees it. Repaint to the elevated dark surface; the ranked-number
     badges + link labels read fine on dark. */
  .hot-keyword-wrapper,
  #subpage-hot-keyword .hot-keyword-wrapper {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Ranked-keyword hover: the site highlights the hovered keyword row with a light
     #f1f1f1 background, so on dark the hovered item shows a bright white band and
     its light label washes out light-on-white. Hover-only, invisible to a
     load-time scan. Darken the hover fill so the highlighted keyword reads. */
  .hot-keyword-wrapper a:hover {
    background-color: #21262d !important;
  }

  /* ---- Nav / tab strips ---------------------------------------------------- */
  .nav,
  .post_nav,
  ul.tabs,
  .tabs,
  .cate_view {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Top-nav tab labels (뽐뿌 / 정보 / 커뮤니티 …). The site paints each tab a mid
     grey (#595959) and its label pure white; the generic body-text rule above
     matches these anchors and drops them to #c4cdd6, which lands at 4.45:1 on
     that grey — a WCAG fail introduced by us, not the site. Restore white. */
  .top-nav > ul > li > a.menu {
    color: #ffffff !important;
  }

  /* Top-nav hover flyouts. Every tab owns a `.sub-menu` panel the site hardcodes
     to pure white (`background:#fff`), and the 포럼 / 오픈포럼 tabs render a wide
     mega-menu inside it (div.sub-menu.forum-favourite, #favorite-forum-panel).
     They are display:none until the tab is hovered, so no load-time scan can see
     them; our light body text then lands light-on-white and the whole flyout is
     unreadable. Repaint to the elevated dark surface.
     The column headers (li.title) are a light-grey #ededed strip whose label we
     lift to #e6edf3 via the heading rule — invisible light-on-light — so they
     need the same dark treatment. */
  .top-nav li .sub-menu,
  .top-nav .sub-menu.forum-favourite,
  #favorite-forum-panel {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  .top-nav .sub-menu li.title,
  #favorite-forum-panel li.title {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* Sub-menu link hover: the site highlights the hovered forum link with a light
     #f1f1f1 background (a subtle grey on the original white). On dark that hover
     ships as a bright white band and our light label lands light-on-white =
     unreadable. Hover-only, so no load-time scan sees it. Darken the hover fill so
     the highlighted link reads. */
  .top-nav .sub-menu a:hover,
  #favorite-forum-panel a:hover {
    background-color: #21262d !important;
  }

  /* Mega-menu featured forum links (li.strong > a — 휴대폰포럼 / PC·인터넷 /
     재테크포럼 / 증권포럼 / DIY포럼 …, the highlighted forum of each column). The
     site paints these with its brand blue #3a66a4 under its OWN !important, so
     the generic body-text rule never reaches them: they keep a blue tuned for
     the original white panel and land at 2.79:1 on the dark flyout — a WCAG fail
     on the menu's most prominent links. Hover-only, so no load-time scan sees
     them. Lift to the theme accent, which keeps the "featured" blue signal and
     reads at ~7:1 on the panel. */
  .top-nav .sub-menu li.strong > a,
  #favorite-forum-panel li.strong > a {
    color: #5fb0e6 !important;
  }

  /* Mega-menu 분류 / ㄱㄴㄷ sort toggle: the SELECTED segment is `span.on`, which
     the site fills with its accent blue (#3a66a4) and white bold text. The
     generic `span.on` pill rule further down flattens it to a neutral dark chip,
     erasing the "which sort is active" signal. Re-assert the brand accent. */
  .top-nav li.extand .off .toggle-btn span.on {
    background-color: #3a66a4 !important;
    color: #ffffff !important;
    border-color: #3a66a4 !important;
  }

  /* Home consult/renewal quick-link tabs (인터넷 / 렌탈 / 휴대폰 / 보험 / 카드 in
     .quick-link.consult-tab.renewal-tabs): the site marks the SELECTED tab by
     colouring its label the accent blue (#0b6bc5) while the others stay near-black
     — colour is the ONLY active-state signal (same bg, no border, same weight).
     The generic body-text rule flattens every tab to the same grey, so the
     selected tab becomes indistinguishable from the rest. Re-assert the accent on
     the active label so the current tab reads. */
  .consult-tab .tab-item.on,
  .renewal-tabs .tab-item.on {
    color: #5fb0e6 !important;
  }

  /* News-hub category tabs (전체뉴스 / 방송·연예 / 스포츠 / … on
     recent_main_article.php?type=news): the site marks the SELECTED tab
     (li.tab02.pick) by colouring its label the accent blue (#1578d5) while the
     others are black — again colour is the only active signal. The body-text rule
     flattens all of them to the same grey, erasing which category is selected.
     Re-assert the accent on the active tab's label. */
  li.tab02.pick,
  li.tab02.pick a {
    color: #5fb0e6 !important;
  }

  /* Board-list "인기 검색어" strip (div.hot_tag — the popular-search chips above
     the list): the site accents the word 인기 in the "인기 검색어" heading with a
     periwinkle bold (#647aff) so the label reads as a heading, not body copy.
     The generic body-text `b` rule greys it to the same tone as 검색어 beside it,
     flattening the accent. Restore it in the theme accent. */
  .hot_tag > span b {
    color: #5fb0e6 !important;
  }

  /* Board-list category filter chips (#navlist in .navcontainer): the site
     renders each category as a near-white grey pill, so the light chip labels
     wash out (light-on-light). Repaint to dark elevated pills; the selected
     chip (a#current) reads a touch brighter to mark the active filter. */
  .navcontainer #navlist a,
  #navlist a {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  .navcontainer #navlist a#current,
  #navlist a#current {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* The "핫/인기" chip marks its 인기 segment with a pure-blue <mark>; on the dark
     pill that blue is too dark — lift to the theme accent and clear the default
     yellow mark highlight. */
  #navlist a mark {
    color: #5fb0e6 !important;
    background-color: transparent !important;
  }

  /* …but the "핫" half of that chip is a separate <em> the site paints pure red
     (#ff0000) to flag the hot-deal filter, while "/인기" stays the blue above. The
     generic body-text `em` rule flattens it to grey, so the two-state 핫/인기 toggle
     loses its hot signal. Restore the refined report-red so 핫 reads warm. */
  #navlist a mark em {
    color: #ff7b72 !important;
  }

  /* Home 이슈 news-keyword chips (li.cate-keyword > a — the tappable person /
     topic tags under the issue-news column, e.g. "린" / "박소영"): the site
     hardcodes a near-white #eef1f8 pill and the label inherits the light body
     text, so each chip washes out light-on-light. Repaint to a dark elevated
     pill with a readable light label. (Short pill, below the white-surface
     scan's size threshold.) */
  li.cate-keyword a {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  .cate_view {
    color: #c4cdd6 !important;
  }

  /* Board-list / forum title bar (.bbs_title — "<board> 입니다." with the
     right-side related-board links). The site paints the bar with a near-white
     linear-gradient as a background-IMAGE (its background-color is transparent),
     so the strip ships bright on dark and is invisible to a background-color
     scan. Repaint to the elevated dark surface and clear the gradient; the board
     title + links inherit the light body text. The small arrow icon on .bname is
     a child background-image and is left intact. */
  .bbs_title {
    background-color: #1c2128 !important;
    background-image: none !important;
    border-color: #2d333b !important;
  }

  /* Error / notice page card (.error2 — the "알립니다" alert box shown on invalid
     board ids, deleted posts, access-denied redirects, etc.). The site frames
     the card with a white JPG (line_02.jpg) set as a background-IMAGE while the
     element's background-color is transparent, so the box ships bright white and
     the muted-grey notice text lands light-on-white = washed out. Both the
     bg-color scan and the audit-blind walk miss it (image, not color). Clear the
     white frame and paint the elevated dark surface; the notice text reads. */
  .error2 {
    background-image: none !important;
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* The "이전 화면" (go back) button under that same notice card is a separate
     div.error3 the site paints #f1f1f1; the light body text on it washes out.
     (92x31 — under the white-surface scan's size floor.) */
  .error3 {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Forum-hub page (recent_forum_article.php — the "포럼" aggregation view): the
     "포럼통합검색" search bar / ranking-sort strip at the top of the forum-ranking
     box (.forum_gategory_top) hardcodes a near-white #f6f6f6 bg, so it ships as a
     bright bar across the dark ranking grid. Repaint to the elevated dark surface;
     the 랭킹순/추천순/가나다순 labels inherit the light body text. */
  .forum_gategory_top {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Forum-hub post rows (recent_forum_article.php): the comment count appended to
     each post title (span.comment_num) is painted the site's link blue (#1d62aa)
     so the "has replies" count reads apart from the title text. The generic
     body-text `span` rule flattens all 25 of them to the same grey as the title,
     so the count disappears into the headline. The theme already accents comment
     counts (.comment-count / .comment_count in the blue group below) — this board
     just spells the class differently, so it slipped through. Same for the
     "포럼통합검색" label on the search bar (li.forum_all_menu, natively #2f73c0). */
  span.comment_num,
  li.forum_all_menu {
    color: #5fb0e6 !important;
  }

  /* Forum-ranking numeral badges (span.ranking_num — the "1"/"2"/… rank chips
     beside each forum name in the ranking grid): the site hardcodes a light-grey
     #f7f7f7 pill, so every rank badge shows a bright square on the dark grid.
     Repaint to a dark elevated pill with a readable light numeral. (22×20 — below
     the white-surface scan's size threshold.) */
  span.ranking_num,
  .ranking_num {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* ---- Login / utility boxes ----------------------------------------------- */
  .login_box,
  .ppomCou,
  .agent,
  .together_goods,
  .addFile,
  .scrap_bx {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Login social-login section (.sc1): the "SNS 계정으로 로그인" label rides a
     white strip (.sns-title .txt) and the bottom "회원 전환 / 되돌아가기" pill
     (.backs) is a near-white grey — both leave the light body text unreadable.
     Repaint to dark so the labels read; SNS brand icons are left untouched. */
  .sc1 .sns-title .txt,
  .sc1 .backs {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  /* Home login-box CTA (img btn_login.jpg inside .login_box, shown logged-out):
     the site's login button is a 277×42 raster JPG — the colourful PPOMPPU logo
     + grey "로그인" baked onto a WHITE background — so it ships as a bright white
     pill on the dark home panel (a raster fill the bg-color scan can't see, and
     a JPG has no transparency to paint through). Invert its lightness so the
     white ground goes dark while hue-rotate keeps the rainbow logo hues intact
     and the grey label readable. Scoped to the btn_login src so nothing else is
     touched. */
  .login_box img[src*="btn_login"] {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Standalone-template PPOMPPU logo (img src=ppomppu.gif): the minimal legacy
     templates (404 / error / access-denied pages under div#wrap) use the GIF
     logo — the colourful "PPOMPPU" wordmark baked onto a WHITE background — so it
     ships as a bright white box on the dark error card (a raster fill the
     bg-color scan can't see; the img's own bg is transparent). The main site
     header uses a transparent logo.png and is untouched. Invert the lightness so
     the white ground goes dark while hue-rotate keeps the neon wordmark hues.
     Scoped to the ppomppu.gif src so nothing else is affected. */
  img[src*="ppomppu.gif"] {
    filter: invert(1) hue-rotate(180deg) !important;
  }

  /* Compact-header login pill (a.loginsmbtn inside .smloginbtnbox — the small
     "로그인" button shown logged-out on board / forum / post / search headers):
     the site hardcodes a pure-white bg, and our light body text colour then
     lands light-on-white = washed out. Repaint to a dark elevated pill with a
     bright readable label. (37×20 — below the white-surface scan's size filter.) */
  a.loginsmbtn,
  .smloginbtnbox a {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ---- Home post panels ---------------------------------------------------- */
  .post_wrap,
  .post_wrap.real_time,
  .post_wrap.best_time,
  .bx-clone,
  .ad-banner,
  .middle-banner,
  li.img_title,
  .ranking_wrap,
  .real_hot_wrap,
  .main_list,
  .main_market {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  /* Home real-time hot list (white <ul>/<li> sliders) */
  .post_wrap ul,
  .post_wrap li,
  .real_time ul,
  .real_time li,
  .js-real_hot ul,
  .js-real_hot li,
  .js-real_ppom ul,
  .js-real_ppom li,
  .main_list ul,
  .main_list li {
    background-color: transparent !important;
  }

  /* ---- Board list table ---------------------------------------------------- */
  #revolution_main_table,
  table.bbs_new1,
  .board_list,
  .info_bg {
    background-color: #14181d !important;
  }

  /* List header row */
  tr.title_bg,
  tr.title_bg td,
  .list_title,
  thead tr,
  thead th {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* Board-list status labels in the number column: the site marks 공지 (notice)
     rows with a blue `#notice_con` label and 알림 (alert) rows with an orange
     `#alert_con` label — the row-type signal. The generic body-text `span` rule
     flattens both to the same neutral grey, so notice and alert become
     indistinguishable. Restore each in the theme accent / warm accent. (Duplicate
     IDs in the legacy markup — the selector matches every instance.)
     Newer consult-style boards (상담실 / 보험상담) ship the same labels under
     hyphenated IDs (#notice-icon / #alert-icon) instead of the underscore form,
     so they escaped the rule and rendered flat grey — cover both spellings. */
  /* Both labels are outlined pills whose 1px border natively MATCHES their text
     colour (blue for 공지, orange for 알림). The blanket `* { border-color }` reset
     flattens that frame to the generic line grey, leaving a coloured label inside a
     mismatched grey box, so re-assert the border to match the restored text. */
  #notice_con,
  #notice-icon {
    color: #5fb0e6 !important;
    border-color: #5fb0e6 !important;
  }

  #alert_con,
  #alert-icon {
    color: #f0883e !important;
    border-color: #f0883e !important;
  }

  /* Notice rows (lightly tinted) */
  tr.baseNotice,
  tr.baseNotice td,
  #headNotice,
  #headNotice td {
    background-color: #1b2026 !important;
  }

  /* Standard deal rows (alternating light tones -> dark) */
  tr.baseList,
  tr.baseList td,
  tr.bbs_new1,
  tr.list1,
  tr.list0 {
    background-color: #161b22 !important;
  }

  tr.baseList:hover,
  tr.baseList:hover td {
    background-color: #1f252d !important;
  }

  /* Hot-deal highlighted row — keep the warm "hot" tint, refined for dark */
  tr.hotpop_bg_color,
  tr.hotpop_bg_color td,
  .hotpop_bg_color {
    background-color: #2a2017 !important;
  }

  /* 장터 (market) board list. Unlike every other board, this one is not a <table>
     but a flex list (div.table-New-contents > ul.cont01|cont02|cont03), and the
     site paints the header row and notice rows #f8f8f8, the odd item rows
     #fdfdfd and the hover state #f5f5f5. None of the table-row rules above reach
     it, so the entire 장터 list ships as bright white rows carrying our light
     text — the worst-hit page type. Repaint each row class to its table
     equivalent so the zebra + hover feedback survive on dark. */
  .table-New-contents .cont01 {
    background-color: #21262d !important;
  }

  .table-New-contents .cont02 {
    background-color: #1b2026 !important;
  }

  .table-New-contents .cont03 {
    background-color: #14181d !important;
  }

  .table-New-contents .cont03:nth-of-type(2n-1) {
    background-color: #161b22 !important;
  }

  .table-New-contents > ul:hover,
  .table-New-contents .cont03:hover {
    background-color: #1f252d !important;
  }

  /* Board-list shopping-forum promo banner (.bridge_area) — site hardcodes a
     near-white bg with dark text; repaint dark so the light text inherits. */
  .bridge_area,
  .bridge_area p {
    background-color: #1c2128 !important;
  }

  /* Search-results "파워링크" sponsored-link block — rendered in the page DOM
     (not a cross-origin ad iframe) with a hardcoded near-white container; repaint
     to the elevated dark surface so the link/description text reads on dark. */
  #div_new_power_link,
  #powerlinknew {
    background-color: #1c2128 !important;
  }

  /* The block's link titles are a deep ad-blue (#071ac8) tuned for white — too
     dark on the repainted surface; lift to the theme accent so they read. The
     title is underlined with a 1px border-bottom in that same ad-blue, which the
     blanket border-color reset flattens to the generic line grey — leaving a grey
     rule under a blue link. Match the underline to the lifted title colour. */
  #powerlinknew a.title,
  #div_new_power_link a.title {
    color: #5fb0e6 !important;
    -webkit-text-fill-color: #5fb0e6 !important;
    border-bottom-color: #5fb0e6 !important;
  }

  /* Search-results scope tabs (전체 / 커뮤니티 / 뉴스 / 장터 …). The site marks the
     selected scope with a 3px #074bc8 bottom border AND a #074bc8 label; the
     blanket `* { border-color }` reset above flattens the underline to the
     generic line colour and the generic anchor rule flattens the label, so the
     active scope becomes indistinguishable from the inactive ones. Re-assert
     both in the theme accent. */
  .result2 .tabs li.active {
    border-bottom-color: #5fb0e6 !important;
  }

  .result2 .tabs li.active a {
    color: #5fb0e6 !important;
  }

  /* Search-results comment-count chip (font.comment-cnt beside each hit title):
     hardcoded #f3f3f3 pill, so the count washes out light-on-light. (14x15 —
     under the white-surface scan's size floor.) */
  font.comment-cnt,
  .results_board .comment-cnt {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  /* News-hub feed (recent_main_article.php?type=news): each headline carries a
     comment-count chip the site hardcodes #f0f0f0, and each thumbnail sits in a
     light-grey #e6e6e6 <i class="Bbox"> frame that shows around photos which
     don't fill the tile. Both are below the white-surface scan's size floor. */
  span.list_comment2,
  .list_comment2 {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  .board_list i.Bbox,
  i.Bbox {
    background-color: #161b22 !important;
  }

  /* ---- Comments ------------------------------------------------------------ */
  #quote,
  .comment_wrapper,
  .comment_template_depth1,
  .comment_template_depth2,
  .comment_view,
  .cmt_list,
  .han02 {
    background-color: transparent !important;
  }

  .comment_wrapper {
    border-color: #2d333b !important;
  }

  /* Nested reply rows get a faint elevation */
  .comment_template_depth2,
  .comment_template_depth3 {
    background-color: #161b22 !important;
  }

  /* Post-author reply highlight: the site paints the author's comment content
     cell a near-white grey (depth2_vote) to flag it as the writer's reply. The
     dark depth wrapper above doesn't cover this inner cell, so it stays bright.
     Repaint to a subtly elevated dark surface so the author signal survives. */
  .comment_template_depth2_vote {
    background-color: #1c2128 !important;
  }

  /* Comment tooltip / balloon (was pale blue) */
  .ppomppu_cmt_balloon,
  #ppomppu_cmt_tooltip {
    background-color: #1c2733 !important;
