  span.gcon.down,
  span.dislike {
    color: #5fb0e6 !important;
  }

  span.like,
  span.gcon.up {
    color: #f0883e !important;
  }

  /* News-hub "HOT" flag (span.nav_hot_ico beside the ranked-post header and hot
     tabs) is a red brand badge the site paints #e80505; the body-text rule drops
     it to grey. Restore the refined red. */
  .nav_hot_ico {
    color: #ff7b72 !important;
  }

  /* Home section-header accents (span.hot_post): the site colours the "HOT" word
     in "실시간 HOT 게시글" red (span.v-font) and the "상품정보" word in
     "뽐뿌 상품정보" blue (an inline color:blue) as section-header signals. The
     broad body-text rule greys both, flattening the headers. Restore the refined
     red / accent blue. (Scoped under .hot_post so the grey .v-font consult-review
     titles elsewhere are untouched.) */
  .hot_post .v-font {
    color: #ff7b72 !important;
  }

  .hot_post span[style*="color:blue"],
  .hot_post span[style*="color: blue"] {
    color: #5fb0e6 !important;
  }

  /* Link blue used for in-content links / counts / comment counts / tabs
     (site uses several near-#1264b1 / #0267cf blues that sit a touch dark on
     this canvas) — brighten to the theme accent so they read clearly. */
  a[href*="copy"],
  .link_blue,
  .comment-count,
  .cnt,
  .comment_count,
  .baseList-head,
  .subject_preface,
  li.on,
  font[color="#1970b3"],
  font[color="#0068c0"],
  font[color="#1e4780"],
  font[color="#0267cf"],
  font[color="#1264b1"],
  font[color="blue"] {
    color: #5fb0e6 !important;
  }

  /* "Report" red (신고) — refine the raw red so it isn't garish on dark */
  font[color="#ff0000"],
  font[color="red"],
  .report,
  .txt_red,
  .red {
    color: #ff7b72 !important;
  }

  /* "Other opinion" orange (다른의견) — refined warm accent */
  font[color="#ff5a00"],
  .txt_orange,
  .orange {
    color: #f0883e !important;
  }

  /* ---- Misc light spans / chips -------------------------------------------- */
  /* Comment sort toggle (최신순 / 작성순): the SELECTED pill is span.on, the
     UNSELECTED one is a plain .myComment > span whose bg the site hardcodes to a
     near-white grey. Style both states to a dark elevated pill with a readable
     light label so neither washes out. */
  .bx_view,
  span.on,
  .myComment > span {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* Selected sort pill reads a touch brighter to mark the active state */
  .myComment > span.on {
    background-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  /* ---- Images: avoid washed-out look on pure-dark, leave content alone ----- */
  /* (no filter on content images — deal photos must stay accurate) */

  /* ---- Scrollbar ----------------------------------------------------------- */
  ::-webkit-scrollbar {
    width: 12px;
    height: 12px;
  }
  ::-webkit-scrollbar-track {
    background: #14181d;
  }
  ::-webkit-scrollbar-thumb {
    background: #2d333b;
    border-radius: 6px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #3a414b;
  }
}
